/// Words whose traditional form the character map cannot express: the compounds that pick a
/// rarer form (头发 -> 頭髮, 皇后 -> 皇后) and the words of the polysemous characters (干部 ->
/// 幹部, 干净 -> 乾淨). Two characters each, so a left-to-right scan finds them without a
/// segmenter. Applied in both directions.
const PHRASES: &[(&str, &str)] = &[
    ("干部", "幹部"),
    ("干活", "幹活"),
    ("骨干", "骨幹"),
    ("干净", "乾淨"),
    ("干杯", "乾杯"),
    ("干燥", "乾燥"),
    ("复杂", "複雜"),
    ("复印", "複印"),
    ("复习", "複習"),
    ("复制", "複製"),
    ("重复", "重複"),
    ("恢复", "恢復"),
    ("制造", "製造"),
    ("制作", "製作"),
    ("制品", "製品"),
    ("制药", "製藥"),
    ("这里", "這裡"),
    ("哪里", "哪裡"),
    ("心里", "心裡"),
    ("里面", "裡面"),
    ("面包", "麵包"),
    ("面条", "麵條"),
    ("面粉", "麵粉"),
    ("头发", "頭髮"),
    ("发型", "髮型"),
    ("理发", "理髮"),
    ("白发", "白髮"),
    ("皇后", "皇后"),
    ("太后", "太后"),
    ("手表", "手錶"),
    ("轻松", "輕鬆"),
    ("放松", "放鬆"),
    ("台风", "颱風"),
    ("于禁", "于禁"),
];

/// Convert `text` to simplified Chinese.
pub fn to_simplified(text: &str) -> String {
    convert_with(text, T2S, PHRASES, true)
}

/// Convert `text` to traditional Chinese.
pub fn to_traditional(text: &str) -> String {
    convert_with(text, S2T, PHRASES, false)
}

/// The conversion itself: the phrase table first (it carries the words the character map
/// cannot express), then the character map. `reverse` picks the direction of the phrase table.
fn convert_with(text: &str, table: [&str; 2], phrases: &[(&str, &str)], reverse: bool) -> String {
    let mut out = String::with_capacity(text.len());
    let mut i = 0;
    while i < text.len() {
        let Some(rest) = text.get(i..) else { break };
        let mut hit = None;
        for (a, b) in phrases {
            let (from, to) = if reverse { (*b, *a) } else { (*a, *b) };
            if rest.starts_with(from) {
                hit = Some((to, from.len()));
                break;
            }
        }
        if let Some((to, n)) = hit {
            out.push_str(to);
            i += n;
            continue;
        }
        let Some(c) = rest.chars().next() else { break };
        out.push(lookup(table, c).unwrap_or(c));
        i += c.len_utf8();
    }
    out
}

/// The character's counterpart in `table`, if it has one.
fn lookup(table: [&str; 2], c: char) -> Option<char> {
    let (from, to) = (table[0], table[1]);
    let mut fi = from.char_indices();
    let mut ti = to.char_indices();
    loop {
        match (fi.next(), ti.next()) {
            (Some((_, fc)), Some((_, tc))) if fc == c => return Some(tc),
            (None, _) | (_, None) => return None,
            _ => {}
        }
    }
}

/// `text.simplify`: convert the selection (or the whole document if nothing is selected) to
/// Simplified Chinese.
pub fn simplify(s: &mut Session, v: &Value) -> CmdResult {
    convert(s, v, to_simplified)
}

/// `text.traditional`: convert the selection (or the whole document if nothing is selected) to
/// Traditional Chinese.
pub fn traditional(s: &mut Session, v: &Value) -> CmdResult {
    convert(s, v, to_traditional)
}

fn convert(s: &mut Session, _v: &Value, f: fn(&str) -> String) -> CmdResult {
    let (a, b) = {
        let (a, b) = s.sel.ordered();
        if a == b {
            // Nothing selected: the whole story the caret is in, as the docs promise.
            let story = a.story;
            (s.doc.start_of(story), s.doc.end_of(story))
        } else {
            (a, b)
        }
    };
    super::controls::check_edit(s, &a, &b)?;

    // Collect the live text, convert it, then replace each paragraph's run.
    for path in s.doc.paths_between(&a, &b) {
        let Some(p) = s.doc.para(a.story, &path) else { continue };
        let from = if path == a.path { a.off } else { 0 };
        let to = if path == b.path { b.off } else { p.len() };
        let src: String = p.text[from..to].to_string();
        if src.is_empty() {
            continue;
        }
        let dst = f(&src);
        if src == dst {
            continue;
        }
        let para = s.doc.para_mut(a.story, &path)?;
        if dst.len() == src.len() {
            para.text.replace_range(from..to, &dst);
        } else {
            let props = para.props_of_char(from).clone();
            para.delete(from, to)?;
            para.insert_text(from, &dst, &props)?;
        }
        para.touch();
    }
    super::sel_result(s)
}

pub fn specs() -> Vec<crate::CommandSpec> {
    vec![
        CommandSpec::new("text.simplify", "Simplify Chinese", "Review › Language", simplify).params(r#"{}"#),
        CommandSpec::new("text.traditional", "Traditional Chinese", "Review › Language", traditional).params(r#"{}"#),
    ]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn simplified_to_traditional() {
        assert_eq!(to_traditional("简体中文"), "簡體中文");
        assert_eq!(to_traditional("计算机"), "計算機");
        assert_eq!(to_traditional("学校"), "學校");
    }

    #[test]
    fn traditional_to_simplified() {
        assert_eq!(to_simplified("繁體中文"), "繁体中文");
        assert_eq!(to_simplified("計算機"), "计算机");
        assert_eq!(to_simplified("學校"), "学校");
    }

    #[test]
    fn non_cjk_is_unchanged() {
        assert_eq!(to_traditional("Hello 123"), "Hello 123");
        assert_eq!(to_simplified("Hello 123"), "Hello 123");
    }

    #[test]
    fn already_target_is_idempotent() {
        let t = to_traditional("简体中文");
        assert_eq!(to_traditional(&t), t);
        let s = to_simplified("繁體中文");
        assert_eq!(to_simplified(&s), s);
    }

    /// The character map covers the common words, not just a handful of characters.
    #[test]
    fn common_words_convert() {
        assert_eq!(to_traditional("国家时间"), "國家時間");
        assert_eq!(to_traditional("说话读书"), "說話讀書");
        assert_eq!(to_traditional("银钱锁头"), "銀錢鎖頭");
    }

    /// A character with several traditional forms keeps its simplified form, so no word comes
    /// out with the wrong character (见面 -> 見麵, 制度 -> 製度, 公里 -> 公裡).
    #[test]
    fn polysemous_characters_stay_correct() {
        assert_eq!(to_traditional("见面"), "見面");
        assert_eq!(to_traditional("制度"), "制度");
        assert_eq!(to_traditional("公里"), "公里");
        assert_eq!(to_traditional("皇后"), "皇后");
        assert_eq!(to_traditional("恢复"), "恢復");
    }

    /// The words that need the rarer form come from the phrase table.
    #[test]
    fn phrases_pick_the_right_form() {
        assert_eq!(to_traditional("干部"), "幹部");
        assert_eq!(to_traditional("干净"), "乾淨");
        assert_eq!(to_traditional("复杂"), "複雜");
        assert_eq!(to_traditional("制造"), "製造");
        assert_eq!(to_traditional("面包"), "麵包");
        assert_eq!(to_traditional("头发"), "頭髮");
        assert_eq!(to_traditional("手表"), "手錶");
    }

    /// The phrase table runs in both directions, so a traditional document comes back.
    #[test]
    fn phrases_work_in_both_directions() {
        assert_eq!(to_simplified("乾淨"), "干净");
        assert_eq!(to_simplified("幹部"), "干部");
        assert_eq!(to_simplified("頭髮"), "头发");
        assert_eq!(to_simplified("麵包"), "面包");
        assert_eq!(to_simplified("這裡"), "这里");
    }
}
